function AgentGlyph({ item, small=false }: { item: WorkItem; small?: boolean }) { return <span className={`tr-agent-glyph g-${item.glyph.toLowerCase()} ${small?"small":""}`} aria-hidden="true"><i/><b>{item.glyph}</b></span>; }
function Status({ tone, children }: { tone: string; children: React.ReactNode }) { return <span className={`tr-status ${tone}`}><span aria-hidden="true" />{children}</span>; }

function HomeSurface({ onFlow }: { onFlow: (flow: Flow) => void }) {
  return <div className="tr-surface tr-home"><header className="tr-page-head"><div><p className="tr-kicker">Friday · Representative design data</p><h1>Good morning,<br/><em>Antonio.</em></h1><p className="tr-deck">Three decisions can clear the path for everything else.</p></div><button className="tr-quiet"><CalendarDays size={16}/>View calendar</button></header>
    <section className="tr-priority"><div className="tr-priority-index">01</div><div><p className="tr-kicker">Owner decision · client commitment</p><h2>Review the client proposal</h2><p>Representative scenario: OATHEN has completed a standards review; PAIGE is waiting for your approval before any delivery.</p><div className="tr-row"><button className="tr-primary" onClick={()=>onFlow("delivery")}>Review with PAIGE <ArrowRight size={15}/></button><button className="tr-link" onClick={()=>onFlow("client")}>Open account</button></div></div></section>
    <div className="tr-columns"><section><div className="tr-section-title"><h2>In motion</h2><span>Representative activity</span></div>{[{n:"Advisory launch campaign",m:"KAVYN · shaping campaign",f:"campaign" as Flow},{n:"Client delivery workflow",m:"ZION · assembling handoff",f:"campaign" as Flow},{n:"Q3 executive brief",m:"Waiting for source data",f:"morning" as Flow}].map((item,i)=><button className="tr-list-row" key={item.n} onClick={()=>onFlow(item.f)}><span className={`tr-work-glyph g${i}`}><Activity size={15}/></span><span><b>{item.n}</b><small>{item.m}</small></span><ArrowRight size={15}/></button>)}</section><section><div className="tr-section-title"><h2>Business pulse</h2><span>Not verified</span></div><div className="tr-pulse"><p>Calendar and email are not connected. PAIGE cannot confirm recent replies or upcoming commitments.</p><button className="tr-quiet">Connect sources</button></div><div className="tr-intelligence-note"><PaigeSymbol territory="command" state="ready" size="sm" treatment="spectral"/><span><small>PAIGE recommends</small><b>Clear the pending client authority request before internal planning.</b></span></div></section></div>
  </div>;
}
